slug: httpclient-getasync-no-throw-on-error-status
stack: dotnet
topic: web-api
level: middle
type: find-bug
grading: auto
tags: [httpclient, status-codes, error-handling, json]
code:
  language: csharp
  harness: statements
  source: |
    using System.Net;
    using System.Text.Json;

    using HttpClient client = new(new NotFoundHandler());

    HttpResponseMessage response = await client.GetAsync("https://api.example.com/orders/42");
    string json = await response.Content.ReadAsStringAsync();
    Order order = JsonSerializer.Deserialize<Order>(json);
    Console.WriteLine(order.Id);

    record Order(int Id, decimal Total);

    class NotFoundHandler : HttpMessageHandler
    {
        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            return Task.FromResult(new HttpResponseMessage(HttpStatusCode.NotFound)
            {
                Content = new StringContent("Order not found")
            });
        }
    }
bugLineSets: [[6], [7]]
fixedSource: |
  using System.Net;
  using System.Text.Json;

  using HttpClient client = new(new NotFoundHandler());

  HttpResponseMessage response = await client.GetAsync("https://api.example.com/orders/42");
  if (!response.IsSuccessStatusCode)
  {
      Console.WriteLine($"Request failed: {(int)response.StatusCode}");
      return;
  }

  string json = await response.Content.ReadAsStringAsync();
  Order order = JsonSerializer.Deserialize<Order>(json);
  Console.WriteLine(order.Id);

  record Order(int Id, decimal Total);

  class NotFoundHandler : HttpMessageHandler
  {
      protected override Task<HttpResponseMessage> SendAsync(
          HttpRequestMessage request, CancellationToken cancellationToken)
      {
          return Task.FromResult(new HttpResponseMessage(HttpStatusCode.NotFound)
          {
              Content = new StringContent("Order not found")
          });
      }
  }
fixedExpect: { kind: output, value: "Request failed: 404" }
